export interface ConnectorConfig {
  /** Pipedrive API token from environment variable PIPEDRIVE_API_TOKEN */
  pipedriveApiToken: string
  /** Typeform field ID for the contact's full name */
  nameFieldId: string
  /** Typeform field ID for the contact's email address */
  emailFieldId: string
  /** Typeform field ID for the contact's phone number (optional) */
  phoneFieldId?: string
  /** Typeform field ID for the company/organization name */
  companyFieldId: string
  /** Typeform field ID for the project description (deal title) */
  projectFieldId: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      text?: string
      email?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface HandleResult {
  organizationId: number
  personId: number
  dealId: number
}

function getAnswerValue(answers: TypeformWebhookPayload['form_response']['answers'], fieldId: string): string | undefined {
  const answer = answers.find((a) => a.field.id === fieldId)
  if (!answer) return undefined
  return answer.text ?? answer.email
}

function requireAnswerValue(answers: TypeformWebhookPayload['form_response']['answers'], fieldId: string, fieldName: string): string {
  const value = getAnswerValue(answers, fieldId)
  if (value === undefined || value === '') {
    throw new Error(`Missing required field: ${fieldName} (field ID: ${fieldId})`)
  }
  return value
}

async function pipedrivePost<T>(url: string, body: unknown, token: string, fetchFn: typeof fetch): Promise<T> {
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Pipedrive API error: ${response.status} ${response.statusText} for ${url}`)
  }

  const data = await response.json()
  return data.data as T
}

export async function handle(payload: TypeformWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch
  const { form_response } = payload
  const { answers } = form_response

  // Validate required fields
  const name = requireAnswerValue(answers, config.nameFieldId, 'name')
  const email = requireAnswerValue(answers, config.emailFieldId, 'email')
  const company = requireAnswerValue(answers, config.companyFieldId, 'company')
  const project = requireAnswerValue(answers, config.projectFieldId, 'project')
  const phone = config.phoneFieldId ? getAnswerValue(answers, config.phoneFieldId) : undefined

  // 1. Create organization
  const orgResponse = await pipedrivePost<{ id: number; name: string }>(
    'https://api.pipedrive.com/v2/organizations',
    { name: company },
    config.pipedriveApiToken,
    fetchFn
  )
  const organizationId = orgResponse.id

  // 2. Create person linked to organization
  const personBody: Record<string, unknown> = {
    name,
    organization_id: organizationId,
    email: [{ value: email, primary: true, label: 'work' }],
  }
  if (phone) {
    personBody.phone = [{ value: phone, primary: true, label: 'work' }]
  }
  const personResponse = await pipedrivePost<{ id: number; name: string; organization_id: number }>(
    'https://api.pipedrive.com/v2/persons',
    personBody,
    config.pipedriveApiToken,
    fetchFn
  )
  const personId = personResponse.id

  // 3. Create deal linked to person
  const dealResponse = await pipedrivePost<{ id: number; title: string; person_id: number }>(
    'https://api.pipedrive.com/v2/deals',
    {
      title: project,
      person_id: personId,
      value: 0,
      currency: 'USD',
    },
    config.pipedriveApiToken,
    fetchFn
  )
  const dealId = dealResponse.id

  return { organizationId, personId, dealId }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, TypeformWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      pipedriveApiToken: 'test-token',
      nameFieldId: 'name_field_id',
      emailFieldId: 'email_field_id',
      phoneFieldId: 'phone_field_id',
      companyFieldId: 'company_field_id',
      projectFieldId: 'project_field_id',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result).toEqual({ organizationId: 12345, personId: 67890, dealId: 54321 })
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    pipedriveApiToken: 'test-token',
    nameFieldId: 'name_field_id',
    emailFieldId: 'email_field_id',
    phoneFieldId: 'phone_field_id',
    companyFieldId: 'company_field_id',
    projectFieldId: 'project_field_id',
  }

  const basePayload: TypeformWebhookPayload = {
    event_id: 'evt_1',
    event_type: 'form_response',
    form_response: {
      form_id: 'form_1',
      token: 'tok_1',
      submitted_at: '2024-01-01T00:00:00Z',
      answers: [
        { type: 'text', text: 'Acme Corp', field: { id: 'company_field_id', type: 'short_text' } },
        { type: 'text', text: 'Laura Smith', field: { id: 'name_field_id', type: 'short_text' } },
        { type: 'email', email: 'laura@example.com', field: { id: 'email_field_id', type: 'email' } },
        { type: 'text', text: '+1-555-123-4567', field: { id: 'phone_field_id', type: 'short_text' } },
        { type: 'text', text: 'Build a new website', field: { id: 'project_field_id', type: 'short_text' } },
      ],
    },
  }

  it('creates organization, person, and deal on happy path', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ data: { id: 111, name: 'Acme Corp' } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ data: { id: 222, name: 'Laura Smith', organization_id: 111 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ data: { id: 333, title: 'Build a new website', person_id: 222 } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const result = await handle(basePayload, { ...baseConfig, fetch })
    expect(result).toEqual({ organizationId: 111, personId: 222, dealId: 333 })
    expect(calls).toHaveLength(3)

    // Verify organization creation request
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://api.pipedrive.com/v2/organizations')
    expect(calls[0].json).toEqual({ name: 'Acme Corp' })
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-token')

    // Verify person creation request
    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toBe('https://api.pipedrive.com/v2/persons')
    expect(calls[1].json).toEqual({
      name: 'Laura Smith',
      organization_id: 111,
      email: [{ value: 'laura@example.com', primary: true, label: 'work' }],
      phone: [{ value: '+1-555-123-4567', primary: true, label: 'work' }],
    })
    expect(calls[1].headers.get('authorization')).toBe('Bearer test-token')

    // Verify deal creation request
    expect(calls[2].method).toBe('POST')
    expect(calls[2].url).toBe('https://api.pipedrive.com/v2/deals')
    expect(calls[2].json).toEqual({
      title: 'Build a new website',
      person_id: 222,
      value: 0,
      currency: 'USD',
    })
    expect(calls[2].headers.get('authorization')).toBe('Bearer test-token')
  })

  it('works without phone field when phoneFieldId is not configured', async () => {
    const configNoPhone: ConnectorConfig = { ...baseConfig, phoneFieldId: undefined }
    const payloadNoPhone: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'phone_field_id'),
      },
    }

    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ data: { id: 111, name: 'Acme Corp' } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ data: { id: 222, name: 'Laura Smith', organization_id: 111 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ data: { id: 333, title: 'Build a new website', person_id: 222 } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const result = await handle(payloadNoPhone, { ...configNoPhone, fetch })
    expect(result).toEqual({ organizationId: 111, personId: 222, dealId: 333 })

    // Person request should not include phone
    expect(calls[1].json).not.toHaveProperty('phone')
  })

  it('throws descriptive error when required name field is missing', async () => {
    const payloadMissingName: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'name_field_id'),
      },
    }

    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    await expect(handle(payloadMissingName, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: name (field ID: name_field_id)'
    )
  })

  it('throws descriptive error when required email field is missing', async () => {
    const payloadMissingEmail: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'email_field_id'),
      },
    }

    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    await expect(handle(payloadMissingEmail, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: email (field ID: email_field_id)'
    )
  })

  it('throws descriptive error when required company field is missing', async () => {
    const payloadMissingCompany: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'company_field_id'),
      },
    }

    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    await expect(handle(payloadMissingCompany, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: company (field ID: company_field_id)'
    )
  })

  it('throws descriptive error when required project field is missing', async () => {
    const payloadMissingProject: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'project_field_id'),
      },
    }

    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    await expect(handle(payloadMissingProject, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: project (field ID: project_field_id)'
    )
  })

  it('throws error with status and endpoint on non-2xx organization response', async () => {
    const { fetch } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ error: 'Unauthorized' }, 401)
      }
      return jsonResponse({}, 200)
    })

    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pipedrive API error: 401 Unauthorized for https://api.pipedrive.com/v2/organizations'
    )
  })

  it('throws error with status and endpoint on non-2xx person response', async () => {
    const { fetch } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ data: { id: 111, name: 'Acme Corp' } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ error: 'Forbidden' }, 403)
      }
      return jsonResponse({}, 200)
    })

    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pipedrive API error: 403 Forbidden for https://api.pipedrive.com/v2/persons'
    )
  })

  it('throws error with status and endpoint on non-2xx deal response', async () => {
    const { fetch } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ data: { id: 111, name: 'Acme Corp' } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ data: { id: 222, name: 'Laura Smith', organization_id: 111 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ error: 'Internal Server Error' }, 500)
      }
      return jsonResponse({}, 200)
    })

    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pipedrive API error: 500 Internal Server Error for https://api.pipedrive.com/v2/deals'
    )
  })
})

